import type { CanaryDetailResponse, CanaryListResponse } from "@/lib/types/bench";
import fs from "node:fs";
import path from "node:path";

// Tests only. The synthetic payloads fixture mode serves for GET /canaries and
// GET /canaries/{name} (public/fixtures, generated by bench/canary TestWriteUIFixtures).

const FIXTURE_DIR = path.resolve(__dirname, "../../public/fixtures");
const read = <T>(file: string): T => JSON.parse(fs.readFileSync(path.join(FIXTURE_DIR, file), "utf8")) as T;

/** Two canaries: nightly (drifted, one model through two providers) and smoke-toy (steady), plus one broken file. */
export const CANARY_LIST_FIXTURE = read<CanaryListResponse>("canaries.json");

/** nightly: baseline, two steady looks, a flag and its confirmation. */
export const CANARY_DRIFTED_FIXTURE = read<CanaryDetailResponse>("canaries.nightly.json");

/** smoke-toy: baseline and one steady look. */
export const CANARY_STEADY_FIXTURE = read<CanaryDetailResponse>("canaries.smoke-toy.json");